#include <stdio.h>
#include <string.h>
#include <ctype.h>

void to_camel(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (str[i] == '_') {
            str[i] = '\0';
            if (i + 1 < len) {
                str[i + 1] = toupper(str[i + 1]);
            }
        }
    }
    printf("%s\n", str);
}

void to_snake(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (isupper(str[i])) {
            if (i > 0) {
                printf("_");
            }
            printf("%c", tolower(str[i]));
        } else {
            printf("%c", str[i]);
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 1;
    }

    char mode[10];
    strcpy(mode, argv[1]);

    if (strcmp(mode, "to_camel") == 0) {
        char str[1024];
        fgets(str, 1024, stdin);
        str[strcspn(str, "\n")] = 0; // remove newline character
        to_camel(str);
    } else if (strcmp(mode, "to_snake") == 0) {
        char str[1024];
        fgets(str, 1024, stdin);
        str[strcspn(str, "\n")] = 0; // remove newline character
        to_snake(str);
    } else {
        printf("INVALID_MODE\n");
        return 1;
    }

    return 0;
}
